    {
        // Cancel any previous in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _isLoading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
