namespace sv_850dc280f56a4c2daa2855f63075e9ca.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    DateTimeOffset Timestamp);

using sv_850dc280f56a4c2daa2855f63075e9ca.Client.Models;

namespace sv_850dc280f56a4c2daa2855f63075e9ca.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_850dc280f56a4c2daa2855f63075e9ca.Client.Models;

namespace sv_850dc280f56a4c2daa2855f63075e9ca.Client.Services;

public sealed class ShipmentServiceHttpClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceHttpClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct)
            ?? throw new InvalidOperationException("Received null response from server.");
    }
}

